using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

Console.WriteLine("Research Agent Starting...");

// Configure the AI client with tool support
var openAiClient = new OpenAIClient(
    Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "your-api-key-here");

IChatClient chatClient = openAiClient
    .GetChatClient("gpt-4o")
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

// Initialize the notebook for storing research findings
var notebook = new ResearchNotebook();

// Register tools available to the agent
var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(
            (string query) => WebSearchTool.SearchAsync(query),
            "web_search",
            "Searches the web for information on a given query and returns relevant results."),
        AIFunctionFactory.Create(
            ([Description("A short title for the note")] string title,
             [Description("The content to save")] string content) =>
            {
                notebook.AddNote(title, content);
                return $"Note saved: '{title}'";
            },
            "take_note",
            "Saves a research note with a title and content for later summarization."),
        AIFunctionFactory.Create(
            () => notebook.GetAllNotes(),
            "read_notes",
            "Reads all previously saved research notes.")
    ]
};

// Prompt the user for a research topic
Console.Write("\nEnter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n{"".PadRight(40, '-')}");

// Run the agent loop
var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your goal is to thoroughly research the given topic using the
        available tools. Follow this process:
        1. Search the web for relevant information (perform 2-3 searches with different queries).
        2. Take notes on the key findings from each search.
        3. Read your notes and synthesize them into a comprehensive summary.
        Present your final summary clearly with key points and conclusions.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
};

var response = await chatClient.GetChatResponseAsync(messages, chatOptions);
Console.WriteLine($"\n{"".PadRight(40, '=')}\nRESEARCH SUMMARY\n{"".PadRight(40, '=')}\n");
Console.WriteLine(response.Text);

// Display collected notes
if (notebook.Notes.Count > 0)
{
    Console.WriteLine($"\n{"".PadRight(40, '-')}\nResearch Notes ({notebook.Notes.Count} saved):");
    foreach (var note in notebook.Notes)
        Console.WriteLine($"  • [{note.Title}]: {note.Content[..Math.Min(note.Content.Length, 80)]}...");
}

// --- Tool implementations ---

/// <summary>Simulates web search results for demonstration purposes.</summary>
static class WebSearchTool
{
    public static Task<string> SearchAsync(string query)
    {
        // In production, replace with a real search API (Bing, Google, etc.)
        var results = $"""
            Search results for: "{query}"

            1. [Overview] {query} is a widely discussed topic with multiple perspectives.
               Key aspects include recent developments, historical context, and future implications.

            2. [Recent News] Recent studies and reports highlight significant progress in {query},
               with experts noting both opportunities and challenges ahead.

            3. [Analysis] According to leading researchers, {query} has transformative potential
               across multiple industries, though adoption varies by region and sector.

            4. [Expert Opinion] Industry leaders suggest that understanding {query} requires
               considering technical, economic, and social dimensions.
            """;

        Console.WriteLine($"  🔍 Searching: \"{query}\"");
        return Task.FromResult(results);
    }
}

/// <summary>Stores research notes collected during the agent's investigation.</summary>
class ResearchNotebook
{
    public List<ResearchNote> Notes { get; } = [];

    public void AddNote(string title, string content)
    {
        Notes.Add(new ResearchNote(title, content));
        Console.WriteLine($"  📝 Note saved: \"{title}\"");
    }

    public string GetAllNotes()
    {
        if (Notes.Count == 0) return "No notes taken yet.";
        return string.Join("\n\n", Notes.Select((n, i) =>
            $"Note {i + 1} - {n.Title}:\n{n.Content}"));
    }
}

